{"policy":"permit (
    principal,
    action == Action::"readNamespaceSecret",
    resource is NamespaceSecret
)
when {
    (principal is User || principal is ServiceAccount) &&
    principal.clearance >= resource.sensitivity &&
    ((resource has ownerUser && resource.ownerUser == principal) ||
     (resource has ownerServiceAccount && resource.ownerServiceAccount == principal)) &&
    context.currentTime < context.serviceAccountToken.expiresAt
};

forbid (
    principal,
    action == Action::"readNamespaceSecret",
    resource is NamespaceSecret
)
when {
    (principal is User || principal is ServiceAccount) &&
    principal.clearance < resource.sensitivity
};

forbid (
    principal,
    action == Action::"readNamespaceSecret",
    resource is NamespaceSecret
)
when {
    (principal is User || principal is ServiceAccount) &&
    !((resource has ownerUser && resource.ownerUser == principal) ||
      (resource has ownerServiceAccount && resource.ownerServiceAccount == principal))
};

forbid (
    principal,
    action == Action::"readNamespaceSecret",
    resource is NamespaceSecret
)
when {
    (principal is User || principal is ServiceAccount) &&
    context.currentTime >= context.serviceAccountToken.expiresAt
};"}
